import datetime

def safe_parse_date(s):
    if not s:
        return None
    try:
        return datetime.datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
    except Exception:
        return None

people = []
for r in range(3, 23):
    last = cell('People', 'D' + str(r))
    birth_s = cell('People', 'E' + str(r))
    admit_s = cell('People', 'F' + str(r))

    b_date = safe_parse_date(birth_s)
    a_date = safe_parse_date(admit_s)

    if b_date is not None and a_date is not None:
